// node story_engine.test.mjs: the JS story generator against stories generated by the Python package
// (tests/fixtures/stories.json, written by scripts/make_story_fixture.py).
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { PyRandom } from './py_random.js';
import { Generator } from './np_random.js';
import { generateStory, diffStories, children, endings, mentions, tellStory } from './story_engine.js';

const F = JSON.parse(readFileSync(new URL('../../../tests/fixtures/stories.json', import.meta.url)));
const close = (a, b) => Math.abs(a - b) <= 1e-12 * Math.max(1, Math.abs(a));

for (const r of F.rng) {
  const py = new PyRandom(r.seed);
  assert.deepEqual(r.random.map(() => py.random()), r.random, `random.Random(${r.seed}).random()`);
  assert.deepEqual(r.choice7.map(() => py.choice([0, 1, 2, 3, 4, 5, 6])), r.choice7, `choice, seed ${r.seed}`);
  const g = new Generator(r.seed);
  r.normal.forEach((v, i) => assert.ok(close(g.normal(0.5, 0.2), v), `default_rng(${r.seed}).normal #${i}`));
}

let exact = 0;
for (const want of F.stories) {
  const got = generateStory(F.spec, want.seed, want.branches);
  const d = diffStories(got, want);
  assert.deepEqual(d, [], `seed ${want.seed} branches ${want.branches}:\n${d.slice(0, 5).join('\n')}`);
  if (JSON.stringify(got) === JSON.stringify(want)) exact++;
  const ch = children(got);
  assert.equal(ch.event_0.length, want.branches);
  assert.equal(endings(got).length, want.branches);
  for (const e of got.events) if (e.phase === 'introduction') assert.ok(mentions(got, e).locations.length === 1);
}
const sd = F.story_data;
assert.equal(JSON.stringify(tellStory(generateStory(F.spec, sd.seed, sd.branches)), null, 2), sd.json, 'story_data.json text');
assert.throws(() => generateStory(F.spec, -1, 3));
assert.throws(() => generateStory(F.spec, 1, 0));
console.log(`story_engine: ${F.rng.length} RNG streams and ${F.stories.length} stories match Python ${F.python} / NumPy ${F.numpy} (${exact} byte-identical)`);
